233: function damagePlayer(amount, sourcePos) {
234:   if (player.dead) return;
235:   player.damage(amount, sourcePos);
236:   // direction indicator, relative to the player's facing
237:   const dx = sourcePos.x - player.position.x;
238:   const dz = sourcePos.z - player.position.z;
239:   const cos = Math.cos(player.yaw), sin = Math.sin(player.yaw);
240:   const lx = dx * cos - dz * sin;
241:   const lz = -dx * sin - dz * cos;
242:   hud.damageDirection(Math.atan2(lx, lz));
243:   if (player.health <= 0) {
244:     player.dead = true;
245:     setTimeout(() => gameOver(), 500);
246:   }
247: }
