249: function onEnemyKilled(enemy, pos) {
250:   const mult = 1 + Math.min(2.5, game.combo * 0.1);
251:   const points = Math.round(enemy.def.score * mult);
252:   game.score += points;
253:   game.kills += 1;
254:   game.totalKills += 1;
255:   game.combo += 1;
256:   game.comboTimer = 4.2;
257:   hud.setScore(game.score);
258:   hud.setKills(game.kills);
259:   hud.setCombo(1 + Math.min(2.5, game.combo * 0.1));
260:   hud.killFeed(enemy.def.name, points, enemy.type === 'titan');
261:   player.addShake(enemy.type === 'titan' ? 0.75 : enemy.type === 'warden' ? 0.28 : 0.12);
262:   audio.kill();
263:   if (enemy.type === 'titan') {
264:     hud.toast('TITAN NEUTRALIZED · +' + points, 2600);
265:   } else if (game.kills > 0 && game.kills % 5 === 0) {
266:     hud.toast(`${game.kills} HOSTILES DOWN · COMBO ×${(1 + Math.min(2.5, game.combo * 0.1)).toFixed(1)}`, 1700);
267:   }
268: }
