270: function fireShot() {
271:   camera.getWorldDirection(shotDir).normalize();
272:   const moving = Math.min(1, player.speed / 7);
273:   const spread = (weapon.ads > 0.55 ? 0.0018 : 0.0085) + moving * 0.006 + (player.onGround ? 0 : 0.02);
274:   _right.crossVectors(shotDir, camera.up).normalize();
275:   _up.crossVectors(_right, shotDir).normalize();
276:   shotDir.addScaledVector(_right, (Math.random() - 0.5) * spread * 2);
277:   shotDir.addScaledVector(_up, (Math.random() - 0.5) * spread * 2);
278:   shotDir.normalize();
279: 
280:   const origin = camera.position.clone();
281:   weapon.getMuzzleWorld(_muzzle);
282:   const enemyHit = enemies.raycast(origin, shotDir, 140);
283: 
284:   if (enemyHit) {
285:     const crit = enemyHit.crit;
286:     const damage = weapon.damage * (crit ? weapon.critMultiplier : 1);
287:     const result = enemyHit.enemy.hit(damage, enemyHit.point, crit);
288:     const color = enemyHit.enemy.def.color;
289:     fx.impact(enemyHit.point, enemyHit.normal, color, crit);
290:     fx.tracer(_muzzle, enemyHit.point, crit ? 0xffffff : 0xffd9a0);
291:     hud.damageNumber(enemyHit.point, camera, damage, crit);
292:     hud.hitmarker(result.killed, crit);
293:     if (crit) hud.toast('CRITICAL HIT', 650);
294:     // small recoil kick on player
295:     player.addRecoil(0.006 + Math.random() * 0.004, (Math.random() - 0.5) * 0.003);
296:     audio.hit(crit);
297:     return;
298:   }
299: 
300:   // static world
301:   raycaster.set(origin, shotDir);
302:   raycaster.far = 160;
303:   const hits = raycaster.intersectObjects(world.solidMeshes, false);
304:   let point = null;
305:   let normal = _normal.set(0, 1, 0);
306:   if (hits.length) {
307:     point = hits[0].point;
308:     if (hits[0].face) normal = hits[0].face.normal.clone().transformDirection(hits[0].object.matrixWorld);
309:     fx.impact(point, normal, 0xffc070, false);
310:     fx.tracer(_muzzle, point, 0xffd9a0);
311:     player.addRecoil(0.006 + Math.random() * 0.004, (Math.random() - 0.5) * 0.003);
312:   } else {
313:     _end.copy(origin).addScaledVector(shotDir, 80);
314:     fx.tracer(_muzzle, _end, 0xffd9a0);
315:     player.addRecoil(0.007 + Math.random() * 0.004, (Math.random() - 0.5) * 0.003);
316:   }
317: }
