323: function buildWaveQueue(wave) {
324:   const q = [];
325:   const wasps = 3 + Math.ceil(wave * 1.45);
326:   const wardens = wave >= 3 ? Math.floor((wave - 1) / 2) : 0;
327:   const titans = wave % 5 === 0 ? 1 : 0;
328:   for (let i = 0; i < wasps; i++) q.push('wasp');
329:   for (let i = 0; i < wardens; i++) q.push('warden');
330:   for (let i = 0; i < titans; i++) q.push('titan');
331:   // shuffle, but keep titans near the end so they arrive as a finale
332:   const shuffled = q.filter(t => t !== 'titan');
333:   for (let i = shuffled.length - 1; i > 0; i--) {
334:     const j = Math.floor(Math.random() * (i + 1));
335:     [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
336:   }
337:   for (let i = 0; i < titans; i++) shuffled.push('titan');
338:   return shuffled;
339: }
340: 
341: function pickSpawn() {
342:   const pts = world.spawnPoints;
343:   const viable = pts.filter(p => Math.hypot(p.x - player.position.x, p.z - player.position.z) > 11);
344:   const pool = viable.length ? viable : pts;
345:   return pool[Math.floor(Math.random() * pool.length)].clone();
346: }
