348: function startWave() {
349:   game.wave += 1;
350:   game.spawnQueue = buildWaveQueue(game.wave);
351:   game.waveActive = true;
352:   game.spawnTimer = 0.5;
353:   game.waveDelay = 0;
354:   const titan = game.spawnQueue.includes('titan');
355:   hud.showWave(
356:     game.wave % 5 === 0 ? 'HEAVY SIGNATURE DETECTED' : 'HOSTILE UPLINK',
357:     `WAVE ${String(game.wave).padStart(2, '0')}`,
358:     titan ? 'TITAN CLASS INBOUND · HOLD FORMATION' : `${game.spawnQueue.length} HOSTILES APPROACHING`,
359:     3.0
360:   );
361:   hud.setObjective(game.spawnQueue.length, game.wave);
362:   hud.setStatus('COMBAT ACTIVE');
363:   hud.toast(titan ? 'TITAN CLASS DETECTED' : `WAVE ${String(game.wave).padStart(2, '0')} INBOUND`, 2200);
364:   audio.wave();
365:   audio.setCombat(true);
366:   if (game.wave > 1 && !titan) {
367:     // randomised tactical chatter
368:     const lines = [
369:       'THEY ARE LEARNING. STAY MOBILE.',
370:       'PERIMETER BREACH DETECTED. KEEP FIRING.',
371:       'CORE IS STABLE. YOU ARE NOT.',
372:       'MULTIPLE SIGNATURES. USE THE COVER.',
373:     ];
374:     setTimeout(() => { if (game.mode === 'playing') hud.toast(lines[Math.floor(Math.random() * lines.length)], 2200); }, 3100);
375:   }
376: }
377: 
378: function endWave() {
379:   game.waveActive = false;
380:   game.waveDelay = 5.2;
381:   const bonus = 200 * game.wave;
382:   game.score += bonus;
383:   hud.setScore(game.score);
384:   player.health = Math.min(player.maxHealth, player.health + 24);
385:   player.armor = Math.min(player.maxArmor, player.armor + 18);
386:   hud.healFlash();
387:   hud.showWave('SECTOR SECURED', `WAVE ${String(game.wave).padStart(2, '0')} CLEAR`, `+${bonus} BONUS · RESUPPLY INBOUND`, 3.2);
388:   hud.toast(`WAVE CLEAR · +${bonus}`, 2400);
389:   hud.setStatus('REARMING');
390:   hud.setObjective(0, game.wave);
391:   audio.setCombat(false);
392:   audio.wave();
393: }
394: 
395: function updateWave(dt) {
396:   if (game.waveActive) {
397:     if (game.spawnQueue.length > 0) {
398:       game.spawnTimer -= dt;
399:       const maxAlive = Math.min(11, 4 + Math.floor(game.wave / 2));
400:       if (game.spawnTimer <= 0 && enemies.countAlive() < maxAlive) {
401:         const type = game.spawnQueue.shift();
402:         const pos = pickSpawn();
403:         const e = enemies.spawn(type, pos, game.wave);
404:         if (type === 'titan') {
405:           hud.toast('TITAN CLASS ON THE PLATFORM', 2600);
406:           player.addShake(0.4);
407:         }
408:         game.spawnTimer = 0.38 + Math.random() * 0.42;
409:       }
410:     }
411:     hud.setObjective(game.spawnQueue.length + enemies.countAlive(), game.wave);
412:     if (game.spawnQueue.length === 0 && enemies.countAlive() === 0) {
413:       endWave();
414:     }
415:   } else {
416:     game.waveDelay -= dt;
417:     if (game.waveDelay <= 0) startWave();
418:   }
419: }
