428: function updateGame(dt, t) {
429:   game.gameTime += dt;
430:   if (game.comboTimer > 0) {
431:     game.comboTimer -= dt;
432:     if (game.comboTimer <= 0 && game.combo > 0) {
433:       game.combo = 0;
434:       hud.setCombo(1);
435:     }
436:   }
437: 
438:   player.update(dt, t, input);
439: 
440:   if (input.reloadQueued) {
441:     input.reloadQueued = false;
442:     weapon.startReload();
443:   }
444:   if (weapon.ammo === 0 && !weapon.reloading) weapon.startReload();
445: 
446:   weapon.update(dt, t, {
447:     aiming: input.aiming && !player.dead,
448:     firing: input.firing,
449:     sprinting: player.sprinting,
450:     speed: player.speed,
451:     lookDelta: player.lookDelta,
452:   });
453: 
454:   if (input.firing && !player.dead && game.mode === 'playing') {
455:     if (weapon.tryFire()) fireShot();
456:   }
457: 
458:   enemies.update(dt, t, player);
459:   fx.update(dt);
460:   world.update(dt, t, player.position);
461: 
462:   updateWave(dt);
463: 
464:   // health regen feedback
465:   if (player.health > game.lastHealth + 0.01) hud.healFlash();
466:   game.lastHealth = player.health;
467: 
468:   hud.updateVitals(player);
469:   hud.updateAmmo(weapon);
470:   hud.updateCrosshair(player, weapon);
471:   hud.drawRadar(enemies.getEnemyPositions(), player, world.core.position, dt);
472:   hud.setScore(game.score);
473:   hud.setKills(game.kills);
474:   if (player.armor < 1) hud.setStatus('SHIELD DEPLETED');
475:   else if (player.health < 35) hud.setStatus('CRITICAL — SEEK COVER');
476:   else if (game.waveActive) hud.setStatus('COMBAT ACTIVE');
477:   else hud.setStatus('REARMING');
478: 
479:   if (player.dead && game.mode === 'playing') {
480:     // handled by damage callback timeout, but guard here too
481:   }
482: 
483:   audio.setCombat(game.waveActive && enemies.countAlive() > 0);
484: }
