486: function updateMenu(dt, t) {
487:   // slow cinematic drift over the rooftop while the menu is visible
488:   const a = Math.sin(t * 0.06) * 0.32;
489:   camera.position.set(Math.sin(a) * 8, 3.4 + Math.sin(t * 0.18) * 0.25, 19 - Math.cos(a) * 2);
490:   camera.lookAt(0, 8 + Math.sin(t * 0.15) * 1.2, -55);
491:   world.update(dt, t, { x: 0, z: 15 });
492:   fx.update(dt);
493:   hud.drawRadar([], player, world.core.position, dt);
494: }
