496: function animate() {
497:   requestAnimationFrame(animate);
498:   const now = performance.now() / 1000;
499:   let dt = now - last;
500:   last = now;
501:   dt = Math.min(0.05, Math.max(0.0001, dt));
502:   const t = now;
503: 
504:   if (game.mode === 'playing') {
505:     updateGame(dt, t);
506:   } else if (game.mode === 'menu') {
507:     updateMenu(dt, t);
508:   } else if (game.mode === 'gameover') {
509:     // keep the rain and city alive behind the result card
510:     world.update(dt, t, player.position);
511:     fx.update(dt);
512:     hud.drawRadar(enemies.getEnemyPositions(), player, world.core.position, dt);
513:   }
514: 
515:   composer.render();
516: 
517:   if (firstFrame) {
518:     firstFrame = false;
519:     setTimeout(() => hud.hideLoading(), 350);
520:   }
521: 
522:   // adaptive resolution for slower GPUs
523:   if (!game.adapted && game.mode === 'playing') {
524:     game.fpsSamples++;
525:     game.fpsAccum += dt;
526:     if (game.fpsSamples >= 120) {
527:       const avg = game.fpsAccum / game.fpsSamples;
528:       if (avg > 0.026 && pixelRatio > 0.85) {
529:         pixelRatio = Math.max(0.85, pixelRatio * 0.8);
530:         renderer.setPixelRatio(pixelRatio);
531:         composer.setPixelRatio(pixelRatio);
532:         composer.setSize(window.innerWidth, window.innerHeight);
533:         bloom.strength *= 0.85;
534:         hud.setQuality('ADAPTIVE · PERFORMANCE');
535:         game.adapted = true;
536:       }
537:       game.fpsSamples = 0;
538:       game.fpsAccum = 0;
539:     }
540:   }
541: }
