214:     const W = 190, H = 190, cx = 95, cy = 95;
215:     const maxRange = 40;
216:     const scale = 78 / maxRange;
217:     this._radarT += dt;
218:     ctx.clearRect(0, 0, W, H);
219: 
220:     // circular backdrop
221:     const bg = ctx.createRadialGradient(cx, cy, 4, cx, cy, 92);
222:     bg.addColorStop(0, 'rgba(12,40,52,0.9)');
223:     bg.addColorStop(0.75, 'rgba(6,18,26,0.82)');
224:     bg.addColorStop(1, 'rgba(3,10,14,0.9)');
225:     ctx.fillStyle = bg;
226:     ctx.beginPath(); ctx.arc(cx, cy, 92, 0, 7); ctx.fill();
227: 
228:     // rings
229:     ctx.strokeStyle = 'rgba(95,246,255,0.16)';
230:     ctx.lineWidth = 1;
231:     for (let i = 1; i <= 3; i++) {
232:       ctx.beginPath(); ctx.arc(cx, cy, (78 / 3) * i, 0, 7); ctx.stroke();
233:     }
234:     ctx.beginPath(); ctx.moveTo(cx - 84, cy); ctx.lineTo(cx + 84, cy); ctx.stroke();
235:     ctx.beginPath(); ctx.moveTo(cx, cy - 84); ctx.lineTo(cx, cy + 84); ctx.stroke();
236: 
237:     // sweep
238:     const sweep = this._radarT * 1.6;
239:     const grad = ctx.createConicGradient(sweep - 0.5, cx, cy);
240:     grad.addColorStop(0, 'rgba(95,246,255,0.0)');
241:     grad.addColorStop(0.06, 'rgba(95,246,255,0.18)');
242:     grad.addColorStop(0.12, 'rgba(95,246,255,0.0)');
243:     grad.addColorStop(1, 'rgba(95,246,255,0)');
244:     ctx.fillStyle = grad;
245:     ctx.beginPath(); ctx.arc(cx, cy, 92, 0, 7); ctx.fill();
246: 
247:     const yaw = player.yaw;
248:     const cos = Math.cos(yaw), sin = Math.sin(yaw);
249:     const project = (wx, wz) => {
250:       const dx = wx - player.position.x;
251:       const dz = wz - player.position.z;
252:       // forward = (-sin, -cos), right = (cos, -sin)
253:       const lx = dx * cos - dz * sin;
254:       const lz = -dx * sin - dz * cos;
255:       return { x: cx + lx * scale, y: cy - lz * scale, d: Math.hypot(dx, dz) };
256:     };
