482:   /* ------------------------------- AI -------------------------------- */
483: 
484:   update(dt, t, player, others, colliders, onFire) {
485:     this.time += dt;
486:     this.fireTimer -= dt;
487:     if (this.attackAnim > 0) this.attackAnim = Math.max(0, this.attackAnim - dt * 4);
488:     if (Math.abs((this.muzzleFlash?.material.opacity) || 0) > 0) {
489:       this.muzzleFlash.material.opacity = Math.max(0, this.muzzleFlash.material.opacity - dt * 12);
490:     }
491: 
492:     // spawn sequence
493:     if (!this.spawned) {
494:       this.spawnT += dt;
495:       const k = Math.min(1, this.spawnT / this.spawnDuration);
496:       const rise = 1 - Math.pow(1 - k, 3);
497:       this.group.visible = k > 0.35;
498:       this.group.position.y = this.baseY - (1 - rise) * (this.def.hover ? 2.4 : 2.8);
499:       this.group.scale.setScalar(0.6 + rise * 0.4);
500:       if (this.portal) {
501:         this.portalRings.forEach((r, i) => {
502:           r.rotation.z += dt * (i ? -2 : 3);
503:           const sc = 1 + Math.sin(t * 8 + i) * 0.08;
504:           r.scale.setScalar((i ? 1.45 : 1) * sc * (1 - k * 0.4));
505:           r.material.opacity = (1 - k) * 0.5;
506:         });
507:         this.portalBeam.material.opacity = (1 - k) * 0.1 + 0.02;
508:         this.portalBeam.scale.setScalar(1 + k * 0.6);
509:         this.portal.scale.setScalar(1 + k * 0.2);
510:         if (k >= 1) {
511:           this.scene.remove(this.portal);
512:           this.portal = null;
513:         }
514:       }
515:       if (k >= 1) {
516:         this.spawned = true;
517:         this.group.scale.setScalar(1);
518:         this.group.position.y = this.baseY;
519:       }
520:       this._animateLimbs(dt, t);
521:       this._updateHealthBar(player.position);
522:       return;
523:     }
524: 
525:     if (!this.alive) return;
526: 
527:     const pos = this.group.position;
528:     const toPlayer = new THREE.Vector3(player.position.x - pos.x, 0, player.position.z - pos.z);
529:     const dist = toPlayer.length();
530:     toPlayer.normalize();
531: 
532:     // steering
533:     const def = this.def;
534:     this.strafeTimer -= dt;
535:     if (this.strafeTimer <= 0) {
536:       this.strafeDir *= -1;
537:       this.strafeTimer = 1.8 + Math.random() * 3;
538:     }
539:     let move = new THREE.Vector3();
540:     if (dist > def.preferred) move.add(toPlayer);
541:     else if (dist < def.preferred * 0.62) move.sub(toPlayer);
542:     const side = new THREE.Vector3(-toPlayer.z, 0, toPlayer.x).multiplyScalar(this.strafeDir * 0.55);
543:     move.add(side);
544:     move.normalize().multiplyScalar(def.speed);
545: 
546:     // separation from neighbours
547:     for (const other of others) {
548:       if (other === this || !other.alive || !other.spawned) continue;
549:       const dx = pos.x - other.group.position.x;
550:       const dz = pos.z - other.group.position.z;
551:       const d2 = dx * dx + dz * dz;
552:       const minD = this.radius + other.radius + 0.4;
553:       if (d2 < minD * minD && d2 > 0.0001) {
554:         const d = Math.sqrt(d2);
555:         move.x += (dx / d) * (minD - d) * 4;
556:         move.z += (dz / d) * (minD - d) * 4;
557:       }
558:     }
559: 
560:     // movement + collision
561:     if (def.hover) {
562:       pos.x += move.x * dt * (0.7 + 0.3 * Math.sin(t * 0.7 + this.phase));
563:       pos.z += move.z * dt;
564:       const targetY = 2.1 + Math.sin(t * 2.1 + this.phase) * 0.35;
565:       pos.y += (targetY - pos.y) * Math.min(1, dt * 2);
566:     } else {
567:       const nx = pos.x + move.x * dt;
568:       const nz = pos.z + move.z * dt;
569:       if (!this._blocked(nx, pos.z, colliders)) pos.x = nx;
570:       if (!this._blocked(pos.x, nz, colliders)) pos.z = nz;
571:       pos.y = 0;
572:     }
573: 
574:     // keep on platform
575:     const maxR = 24.6;
576:     const r = Math.hypot(pos.x, pos.z);
577:     if (r > maxR) { pos.x *= maxR / r; pos.z *= maxR / r; }
578: 
579:     // face player
580:     const yaw = Math.atan2(toPlayer.x, toPlayer.z);
581:     this.group.rotation.y = yaw;
582: 
583:     this._animateLimbs(dt, t);
584: 
585:     // attack
586:     const inRange = dist < def.attackRange;
587:     const canSee = true;
588:     if (inRange && canSee && this.fireTimer <= 0) {
589:       this.fireTimer = def.fireDelay * (0.72 + Math.random() * 0.5);
590:       this.attackAnim = 1;
591:       this._fire(player, onFire, dist);
592:     }
593: 
594:     if (this.muzzleFlash) this.muzzleFlash.material.opacity = Math.max(0, this.muzzleFlash.material.opacity - dt * 10);
595:     this._updateHealthBar(player.position);
596:   }
597: 
598:   _blocked(x, z, colliders) {
599:     const r = this.radius;
600:     for (const c of colliders) {
601:       if (x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r) return true;
602:     }
603:     return false;
604:   }
605: 
606:   _animateLimbs(dt, t) {
607:     const speed = this.def.speed;
608:     if (this.type === 'wasp') {
609:       for (let i = 0; i < this.rotors.length; i++) {
610:         this.rotors[i].rotation.y += dt * (18 + i * 1.5);
611:       }
612:       this.group.rotation.z = Math.sin(t * 1.4 + this.phase) * 0.08;
613:       this.underGlow.material.opacity = 0.25 + Math.sin(t * 5 + this.phase) * 0.1;
614:       this.gun.position.z = 0.15 - this.attackAnim * 0.12;
615:       this.gun.rotation.x = -this.attackAnim * 0.12;
616:     } else if (this.type === 'warden') {
617:       const walk = Math.sin(t * 5 + this.phase);
618:       this.legs.forEach((l, i) => {
619:         const ph = i ? 0 : Math.PI;
620:         l.leg.rotation.x = Math.sin(t * 4.2 + ph) * 0.34;
621:         l.knee.rotation.x = Math.max(0, Math.cos(t * 4.2 + ph)) * 0.55;
622:       });
623:       this.group.position.y = Math.abs(Math.sin(t * 4.2)) * 0.045;
624:       this.arms[1].rotation.x = -0.1 - this.attackAnim * 0.15;
625:       this.head.rotation.y = Math.sin(t * 0.7) * 0.12;
626:     } else {
627:       this.legs.forEach((l, i) => {
628:         const ph = (i % 2 ? 0 : Math.PI) + (l.front > 0 ? 0.4 : 0);
629:         l.leg.rotation.x = Math.sin(t * 2.2 + ph) * 0.2;
630:         l.knee.rotation.x = Math.max(0, Math.cos(t * 2.2 + ph)) * 0.32;
631:       });
632:       this.group.position.y = Math.abs(Math.sin(t * 2.2)) * 0.08;
633:       this.eyeGlow.scale.setScalar(3.2 + Math.sin(t * 4) * 0.4);
634:       this.core.scale.setScalar(1 + Math.sin(t * 3.2) * 0.08);
635:       this.head.rotation.y = Math.sin(t * 0.5) * 0.15;
636:     }
