111:       depthWrite: false,
112:       fog: false,
113:       uniforms: {
114:         uTime: { value: 0 },
115:         uTop: { value: new THREE.Color(0x02050c) },
116:         uMid: { value: new THREE.Color(0x0b1a2e) },
117:         uHorizon: { value: new THREE.Color(0x3a1b3d) },
118:         uGlow: { value: new THREE.Color(0x8c2a4a) },
119:       },
120:       vertexShader: `
121:         varying vec3 vDir;
122:         void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
123:       fragmentShader: `
124:         uniform float uTime; uniform vec3 uTop, uMid, uHorizon, uGlow;
125:         varying vec3 vDir;
126:         float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
127:         float noise(vec2 p){
128:           vec2 i = floor(p), f = fract(p); f = f*f*(3.0-2.0*f);
129:           return mix(mix(hash(i), hash(i+vec2(1,0)), f.x), mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), f.x), f.y);
130:         }
131:         float fbm(vec2 p){
132:           float v = 0.0, a = 0.5;
133:           for(int i=0;i<5;i++){ v += a*noise(p); p *= 2.03; a *= 0.5; }
134:           return v;
135:         }
136:         void main(){
137:           vec3 d = normalize(vDir);
138:           float h = max(d.y, 0.0);
139:           vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.28, h));
140:           col = mix(col, uTop, smoothstep(0.12, 0.85, h));
141:           // city light pollution bloom near horizon
142:           float glow = pow(max(0.0, 1.0 - h*2.4), 2.0) * (0.55 + 0.45*noise(vec2(atan(d.z,d.x)*3.0, 2.0)));
143:           col += uGlow * glow * 0.22;
144:           // high cloud bands
145:           vec2 uv = vec2(atan(d.z, d.x) * 1.7 + uTime * 0.004, d.y * 2.2);
146:           float cl = smoothstep(0.5, 0.85, fbm(uv * 2.4 + fbm(uv * 1.5)));
147:           col = mix(col, vec3(0.10,0.12,0.18), cl * smoothstep(0.04, 0.5, h) * 0.55);
148:           // stars
149:           if (h > 0.12) {
150:             vec2 sp = d.xz / max(d.y, 0.1);
151:             float star = step(0.9975, hash(floor(sp * 90.0)));
152:             col += vec3(0.55,0.7,0.9) * star * smoothstep(0.12, 0.4, h) * 0.55;
153:           }
154:           gl_FragColor = vec4(col, 1.0);
155:         }`,
156:     });
157:     this.skyMat = mat;
158:     this.sky = new THREE.Mesh(geo, mat);
159:     this.sky.frustumCulled = false;
160:     this.scene.add(this.sky);
161: 
162:     // moon glow + core
163:     const moon = new THREE.Sprite(new THREE.SpriteMaterial({
164:       map: this.textures.glowWhite, color: 0xa9d8ff, transparent: true,
165:       opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
166:     }));
167:     moon.scale.set(190, 190, 1);
168:     moon.position.set(-300, 215, -620);
169:     this.scene.add(moon);
170: 
171:     const moonCore = new THREE.Sprite(new THREE.SpriteMaterial({
172:       map: this.textures.glowWhite, color: 0xf2fbff, transparent: true,
173:       opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
174:     }));
175:     moonCore.scale.set(44, 44, 1);
176:     moonCore.position.copy(moon.position);
177:     this.scene.add(moonCore);
178: 
179:     // high haze clouds
180:     this.clouds = [];
181:     for (let i = 0; i < 9; i++) {
182:       const s = new THREE.Sprite(new THREE.SpriteMaterial({
183:         map: this.textures.cloud, color: i % 3 === 0 ? 0x8b617a : 0x3a5368,
184:         transparent: true, opacity: 0.26 + this.rnd() * 0.14, depthWrite: false, fog: false,
185:       }));
186:       const a = this.rnd() * TAU, r = 320 + this.rnd() * 260;
187:       s.position.set(Math.cos(a) * r, 80 + this.rnd() * 150, Math.sin(a) * r);
188:       const sc = 260 + this.rnd() * 260;
189:       s.scale.set(sc, sc * 0.48, 1);
190:       s.userData.speed = 0.4 + this.rnd() * 0.7;
191:       this.clouds.push(s);
192:       this.scene.add(s);
193:     }
194:   }
