196:   /* ---------------------------------------------------------------- */
197:   /*  layered city                                                    */
198:   /* ---------------------------------------------------------------- */
199: 
200:   _buildCity() {
201:     const rnd = this.rnd;
202:     const variants = 6;
203:     // Buildings are instanced in four size classes so window grids keep a
204:     // believable floor height instead of stretching across entire towers.
205:     const scaleClasses = [
206:       { x: 0.55, y: 0.58 },
207:       { x: 1.0, y: 1.1 },
208:       { x: 1.7, y: 2.0 },
209:       { x: 2.5, y: 2.9 },
210:     ];
211:     const materials = [];
212:     for (let v = 0; v < variants; v++) {
213:       const maps = createBuildingTextures(v, 40 + v);
214:       for (const cls of scaleClasses) {
215:         const map = maps.map.clone();
216:         const emissive = maps.emissive.clone();
217:         for (const t of [map, emissive]) {
218:           t.repeat.set(cls.x, cls.y);
219:           t.needsUpdate = true;
220:         }
221:         materials.push(new THREE.MeshStandardMaterial({
222:           map,
223:           emissiveMap: emissive,
224:           emissive: 0xffffff,
225:           emissiveIntensity: 1.55,
226:           roughness: 0.78,
227:           metalness: 0.22,
228:           envMapIntensity: 0.55,
229:         }));
230:       }
231:     }
232:     const classFor = (b) => {
233:       const size = Math.max(b.w, b.d, b.h * 0.26);
234:       if (size > 34 || b.h > 170) return 3;
235:       if (size > 24 || b.h > 110) return 2;
236:       if (size > 16 || b.h > 58) return 1;
237:       return 0;
238:     };
239: 
240:     this.buildings = [];
241:     const rings = [
242:       { count: 26, r0: 58, r1: 112, base: -34, h0: 34, h1: 82, w0: 10, w1: 22, jitter: 0.9 },
243:       { count: 30, r0: 128, r1: 215, base: -52, h0: 55, h1: 132, w0: 12, w1: 30, jitter: 1.0 },
244:       { count: 30, r0: 245, r1: 400, base: -72, h0: 80, h1: 230, w0: 16, w1: 42, jitter: 1.1 },
245:     ];
246: 
247:     for (const ring of rings) {
248:       for (let i = 0; i < ring.count; i++) {
249:         const a = (i / ring.count) * TAU + (rnd() - 0.5) * ((TAU / ring.count) * 0.6);
250:         const r = ring.r0 + rnd() * (ring.r1 - ring.r0);
251:         const w = ring.w0 + rnd() * (ring.w1 - ring.w0);
252:         const d = ring.w0 + rnd() * (ring.w1 - ring.w0);
253:         const h = ring.h0 + rnd() * (ring.h1 - ring.h0);
254:         this.buildings.push({
255:           x: Math.cos(a) * r,
256:           z: Math.sin(a) * r,
257:           w, d, h,
258:           base: ring.base + rnd() * 10,
259:           rot: (rnd() - 0.5) * 0.35,
260:           variant: Math.floor(rnd() * variants),
261:           ring: rings.indexOf(ring),
262:           angle: a,
263:           radius: r,
264:         });
265:       }
266:     }
267: 
268:     // Instance the building shells per material
269:     const dummy = new THREE.Object3D();
270:     const box = new THREE.BoxGeometry(1, 1, 1);
271:     const byMat = Array.from({ length: variants * scaleClasses.length }, () => []);
272:     for (const b of this.buildings) byMat[b.variant * scaleClasses.length + classFor(b)].push(b);
273: 
274:     byMat.forEach((list, mi) => {
275:       if (!list.length) return;
276:       const inst = new THREE.InstancedMesh(box, materials[mi], list.length);
277:       inst.castShadow = false;
278:       inst.receiveShadow = false;
279:       list.forEach((b, i) => {
280:         dummy.position.set(b.x, b.base + b.h / 2, b.z);
281:         dummy.rotation.set(0, b.rot, 0);
282:         dummy.scale.set(b.w, b.h, b.d);
283:         dummy.updateMatrix();
284:         inst.setMatrixAt(i, dummy.matrix);
285:       });
286:       inst.instanceMatrix.needsUpdate = true;
287:       this.scene.add(inst);
288:     });
289: 
290:     // Rooftop clutter (instanced dark boxes)
291:     const roofMat = new THREE.MeshStandardMaterial({ color: 0x141b21, roughness: 0.7, metalness: 0.55, envMapIntensity: 0.7 });
292:     const roofItems = [];
293:     const antennaItems = [];
294:     const antennaMat = new THREE.MeshStandardMaterial({ color: 0x2b343c, roughness: 0.5, metalness: 0.8 });
295:     const beaconPositions = [];
296: 
297:     for (const b of this.buildings) {
298:       const top = b.base + b.h;
299:       const n = 1 + Math.floor(rnd() * 3);
300:       for (let i = 0; i < n; i++) {
301:         const w = b.w * (0.12 + rnd() * 0.28);
302:         const d = b.d * (0.12 + rnd() * 0.28);
303:         const h = 1 + rnd() * 4.5;
304:         roofItems.push({
305:           x: b.x + (rnd() - 0.5) * b.w * 0.6,
306:           z: b.z + (rnd() - 0.5) * b.d * 0.6,
307:           y: top + h / 2,
308:           w, h, d,
309:         });
310:       }
311:       if (rnd() > 0.32) {
312:         const ah = 4 + rnd() * 16;
313:         antennaItems.push({ x: b.x + (rnd() - 0.5) * b.w * 0.3, z: b.z + (rnd() - 0.5) * b.d * 0.3, y: top + ah / 2, h: ah });
314:         beaconPositions.push(new THREE.Vector3(b.x, top + ah + 0.3, b.z));
315:       }
316:       if (b.ring === 0 && rnd() > 0.6) {
317:         beaconPositions.push(new THREE.Vector3(b.x, top + 0.5, b.z));
318:       }
319:     }
320: 
321:     const makeInstances = (items, geo, mat) => {
322:       const inst = new THREE.InstancedMesh(geo, mat, items.length);
323:       items.forEach((it, i) => {
324:         dummy.position.set(it.x, it.y, it.z);
325:         dummy.rotation.set(0, it.rot || 0, 0);
326:         dummy.scale.set(it.w ?? 1, it.h ?? 1, it.d ?? 1);
327:         dummy.updateMatrix();
328:         inst.setMatrixAt(i, dummy.matrix);
329:       });
330:       inst.instanceMatrix.needsUpdate = true;
331:       this.scene.add(inst);
332:       return inst;
333:     };
334:     makeInstances(roofItems, new THREE.BoxGeometry(1, 1, 1), roofMat);
335:     makeInstances(antennaItems, new THREE.CylinderGeometry(0.18, 0.55, 1, 5), antennaMat);
336: 
337:     // Neon edge strips instanced by colour
338:     const stripColors = [0x5ff6ff, 0xff2e88, 0xffb43c, 0x27ffc3];
339:     const stripGroups = [[], [], [], []];
340:     for (const b of this.buildings) {
341:       if (rnd() > 0.72) continue;
342:       const ci = Math.floor(rnd() * 4);
343:       const top = b.base + b.h;
344:       stripGroups[ci].push({ x: b.x, z: b.z, y: (b.base + top) / 2, w: b.w * 1.012, h: b.h * 0.92, d: 0.16, rot: b.rot, edge: rnd() > 0.5 ? 1 : -1 });
345:     }
346:     stripGroups.forEach((list, i) => {
347:       if (!list.length) return;
348:       const mat = new THREE.MeshBasicMaterial({ color: stripColors[i], toneMapped: false });
349:       const geo = new THREE.BoxGeometry(1, 1, 0.2);
350:       const inst = new THREE.InstancedMesh(geo, mat, list.length);
351:       list.forEach((s, k) => {
352:         // A thin vertical strip on one face of each building.
353:         const off = s.edge * s.w * 0.49;
354:         dummy.position.set(s.x + Math.cos(s.rot) * off, s.y, s.z - Math.sin(s.rot) * off);
355:         dummy.rotation.set(0, s.rot, 0);
356:         dummy.scale.set(0.35, s.h, 0.35);
357:         dummy.updateMatrix();
358:         inst.setMatrixAt(k, dummy.matrix);
359:       });
360:       inst.instanceMatrix.needsUpdate = true;
361:       this.scene.add(inst);
362:     });
363: 
364:     // Beacons as a blinking Points cloud
365:     const beaconGeo = new THREE.BufferGeometry().setFromPoints(beaconPositions);
366:     this.beaconMat = new THREE.PointsMaterial({
367:       color: 0xff3344, size: 3.2, map: this.textures.glowPink, transparent: true,
368:       opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true, fog: false,
369:     });
370:     this.scene.add(new THREE.Points(beaconGeo, this.beaconMat));
371: 
372:     // Crown ring on the tallest near tower + signature spire
373:     this._buildLandmarks();
374: 
375:     // Billboards + neon signs
376:     this._buildSignage();
377:     this._buildExtraSkyline();
378:     this._buildCityDetail();
379:   }
380: 
381:   /* ---------------------------------------------------------------- */
382:   /*  close-range metropolis detail                                   */
383:   /* ---------------------------------------------------------------- */
384: 
385:   _buildCityDetail() {
386:     const rnd = this.rnd;
387:     const near = this.buildings.filter(b => b.ring === 0);
388:     const mid = this.buildings.filter(b => b.ring === 1);
389: 
390:     const structural = new THREE.MeshStandardMaterial({ color: 0x090f15, roughness: 0.52, metalness: 0.62, envMapIntensity: 0.9 });
391:     const structuralLight = new THREE.MeshStandardMaterial({ color: 0x17212a, roughness: 0.62, metalness: 0.5, envMapIntensity: 0.8 });
392:     const cyan = new THREE.MeshBasicMaterial({ color: 0x5ff6ff, toneMapped: false, transparent: true, opacity: 0.78 });
393:     const pink = new THREE.MeshBasicMaterial({ color: 0xff2e88, toneMapped: false, transparent: true, opacity: 0.7 });
394:     const amber = new THREE.MeshBasicMaterial({ color: 0xffb43c, toneMapped: false, transparent: true, opacity: 0.72 });
395:     const windowBand = new THREE.MeshBasicMaterial({ color: 0xbff8ff, toneMapped: false, transparent: true, opacity: 0.85 });
396: 
397:     /* --- lower district rooftops just beyond the arena ------------ */
398:     const lowMaps = createBuildingTextures(4, 909);
399:     lowMaps.map.repeat.set(2.4, 1.1);
400:     lowMaps.emissive.repeat.set(2.4, 1.1);
401:     const lowMat = new THREE.MeshStandardMaterial({
402:       map: lowMaps.map, emissiveMap: lowMaps.emissive, emissive: 0xffffff,
403:       emissiveIntensity: 1.15, roughness: 0.82, metalness: 0.2, envMapIntensity: 0.45,
404:     });
405:     const tankMat = new THREE.MeshStandardMaterial({ color: 0x1a232b, roughness: 0.58, metalness: 0.66, envMapIntensity: 1.0 });
406:     const tankBand = new THREE.MeshStandardMaterial({ color: 0x39454f, roughness: 0.42, metalness: 0.82, envMapIntensity: 1.2 });
407: 
408:     const rooftopCount = this.mobile ? 10 : 13;
409:     for (let i = 0; i < rooftopCount; i++) {
410:       const a = (i / rooftopCount) * TAU + 0.17 + (rnd() - 0.5) * 0.16;
411:       const r = 49 + rnd() * 11;
412:       const w = 6.5 + rnd() * 5;
413:       const d = 6.5 + rnd() * 5;
414:       const top = 0.4 + rnd() * 4.6;
415:       const body = new THREE.Mesh(new THREE.BoxGeometry(w, top + 30, d), lowMat);
416:       body.position.set(Math.cos(a) * r, top - (top + 30) / 2, Math.sin(a) * r);
417:       body.rotation.y = (rnd() - 0.5) * 0.4;
418:       this.scene.add(body);
419: 
420:       // roof lip + bright edge
421:       const lip = new THREE.Mesh(new THREE.BoxGeometry(w * 1.06, 0.42, d * 1.06), structuralLight);
422:       lip.position.set(body.position.x, top + 0.18, body.position.z);
423:       lip.rotation.y = body.rotation.y;
424:       this.scene.add(lip);
425:       const edgeMat = i % 3 === 0 ? pink : (i % 3 === 1 ? cyan : amber);
426:       const edge = new THREE.Mesh(new THREE.BoxGeometry(w * 1.08, 0.1, 0.1), edgeMat);
427:       edge.position.set(body.position.x, top + 0.42, body.position.z + d * 0.54);
428:       edge.rotation.y = body.rotation.y;
429:       this.scene.add(edge);
430: 
431:       // rooftop plant: AC block, vent stack, antenna and blinking light
432:       const ac = new THREE.Mesh(new THREE.BoxGeometry(w * 0.3, 1.0 + rnd() * 0.8, d * 0.28), structural);
433:       ac.position.set(body.position.x + (rnd() - 0.5) * w * 0.4, top + 0.8, body.position.z + (rnd() - 0.5) * d * 0.35);
434:       ac.rotation.y = body.rotation.y + rnd();
435:       this.scene.add(ac);
436:       const stack = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.24, 2 + rnd() * 1.6, 7), tankBand);
437:       stack.position.set(body.position.x - w * 0.24, top + 1.4, body.position.z + d * 0.2);
438:       this.scene.add(stack);
439:       const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.09, 6 + rnd() * 8, 5), structural);
440:       mast.position.set(body.position.x + w * 0.22, top + 4.6, body.position.z - d * 0.18);
441:       this.scene.add(mast);
442:       const beacon = new THREE.Sprite(new THREE.SpriteMaterial({
443:         map: this.textures.glowPink, color: 0xff4455, transparent: true, opacity: 0.8,
444:         blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
445:       }));
446:       beacon.scale.set(1.4, 1.4, 1);
447:       beacon.position.set(mast.position.x, mast.position.y + 3.4, mast.position.z);
448:       this.scene.add(beacon);
449: 
450:       // small holo panel facing the arena
451:       if (i % 3 === 0) {
452:         const dir = new THREE.Vector3(-body.position.x, 0, -body.position.z).normalize();
453:         const panel = new THREE.Mesh(new THREE.PlaneGeometry(3.6, 1.8), new THREE.MeshBasicMaterial({
454:           map: createBillboardTexture(i % 6), transparent: true, opacity: 0.85,
455:           side: THREE.DoubleSide, toneMapped: true,
456:         }));
457:         panel.position.set(body.position.x + dir.x * (w * 0.55), top + 2.5, body.position.z + dir.z * (d * 0.55));
458:         panel.lookAt(0, top + 2.5, 0);
459:         this.scene.add(panel);
460:         const panelGlow = new THREE.Sprite(new THREE.SpriteMaterial({
461:           map: this.textures.glowCyan, color: 0x4bd6ff, transparent: true, opacity: 0.18,
462:           blending: THREE.AdditiveBlending, depthWrite: false,
463:         }));
464:         panelGlow.scale.set(8, 8, 1);
465:         panelGlow.position.copy(panel.position);
466:         this.scene.add(panelGlow);
467:       }
468:     }
469: 
470:     /* --- horizontal floor ledges break up the facades -------------- */
471:     const ledgeGeo = new THREE.BoxGeometry(1, 1, 1);
472:     const ledges = [];
473:     for (const b of [...near, ...mid]) {
474:       const n = 3 + Math.floor(rnd() * 3);
475:       for (let k = 0; k < n; k++) {
476:         const y = b.base + b.h * (0.18 + (k / n) * 0.68 + rnd() * 0.06);
477:         ledges.push({
478:           x: b.x, z: b.z, y, rot: b.rot,
479:           w: b.w * (1.025 + rnd() * 0.012), h: 0.24 + rnd() * 0.2, d: b.d * (1.025 + rnd() * 0.012),
480:         });
481:       }
482:     }
483:     const ledgeInst = new THREE.InstancedMesh(ledgeGeo, structuralLight, ledges.length);
484:     const dummy = new THREE.Object3D();
485:     ledges.forEach((l, i) => {
486:       dummy.position.set(l.x, l.y, l.z);
487:       dummy.rotation.set(0, l.rot, 0);
488:       dummy.scale.set(l.w, l.h, l.d);
489:       dummy.updateMatrix();
490:       ledgeInst.setMatrixAt(i, dummy.matrix);
491:     });
492:     ledgeInst.instanceMatrix.needsUpdate = true;
493:     this.scene.add(ledgeInst);
494: 
495:     // thin lit rails along a selection of those ledges
496:     const railLights = [];
497:     for (let i = 0; i < ledges.length; i += 3) {
498:       const l = ledges[i];
499:       const dir = new THREE.Vector3(-l.x, 0, -l.z).normalize();
500:       railLights.push({ x: l.x + dir.x * l.w * 0.52, z: l.z + dir.z * l.d * 0.52, y: l.y + 0.2, rot: l.rot, w: l.w * 0.9 });
501:     }
502:     const lightInst = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 0.07, 0.07), cyan, railLights.length);
503:     railLights.forEach((l, i) => {
504:       dummy.position.set(l.x, l.y, l.z);
505:       dummy.rotation.set(0, l.rot, 0);
506:       dummy.scale.set(l.w, 1, 1);
507:       dummy.updateMatrix();
508:       lightInst.setMatrixAt(i, dummy.matrix);
509:     });
510:     lightInst.instanceMatrix.needsUpdate = true;
511:     this.scene.add(lightInst);
512: 
513:     /* --- skybridges link the near towers --------------------------- */
514:     let bridgeCount = 0;
515:     for (let i = 0; i < near.length && bridgeCount < (this.mobile ? 6 : 9); i += 2) {
516:       const a = near[i], b = near[(i + 1) % near.length];
517:       if (!a || !b) continue;
518:       const dx = b.x - a.x, dz = b.z - a.z;
519:       const dist = Math.hypot(dx, dz);
520:       if (dist < 12 || dist > 54) continue;
521:       const topA = a.base + a.h, topB = b.base + b.h;
522:       const y = Math.min(topA, topB) - 6 - rnd() * 14;
523:       if (y < 9) continue;
524:       const len = dist - 5;
525:       const g = new THREE.Group();
526:       const deck = new THREE.Mesh(new THREE.BoxGeometry(len, 2.1, 4.4), structural);
527:       g.add(deck);
528:       const roof = new THREE.Mesh(new THREE.BoxGeometry(len * 1.01, 0.28, 4.6), structuralLight);
529:       roof.position.y = 1.18;
530:       g.add(roof);
531:       const under = new THREE.Mesh(new THREE.BoxGeometry(len * 0.98, 0.16, 4.2), i % 3 ? cyan : pink);
532:       under.position.y = -1.12;
533:       g.add(under);
534:       for (const zs of [-1, 1]) {
535:         const windows = new THREE.Mesh(new THREE.BoxGeometry(len * 0.92, 0.38, 0.06), windowBand);
536:         windows.position.set(0, 0.15, zs * 2.23);
537:         g.add(windows);
